use vstd::prelude::*;

verus! {

/// Mathematical sign-classification used in the spec.
spec fn sign_class(v: int) -> int {
    if v < 0 { -1 }
    else if v == 0 { 0 }
    else { 1 }
}

/// Executable helper for i8 values.
fn sign_i8(v: i8) -> (r: i8)
    ensures
        // Relate the concrete result to the mathematical classification.
        r as int == sign_class(v as int),
        // Also pin down the allowed outputs.
        r == -1i8 || r == 0i8 || r == 1i8,
{
    if v < 0 {
        -1
    } else if v == 0 {
        0
    } else {
        1
    }
}

fn sign(x: Vec<i8>) -> (result: Vec<i8>)
    requires
        x.len() > 0,
    ensures
        result.len() == x.len(),
        forall|i: int|
            0 <= i < x.len() ==>
                result[i] as int == sign_class(x[i] as int),
{
    let n = x.len();
    let mut result: Vec<i8> = Vec::new();
    let mut i: usize = 0;

    while i < n
        invariant
            n == x.len(),
            result.len() == i,
            i <= n,
            forall|j: int|
                0 <= j < i ==>
                    result[j] as int == sign_class(x[j] as int),
        decreases n - i,
    {
        let r = sign_i8(x[i]);
        result.push(r);
        i = i + 1;
    }

    result
}

} // verus!

